using ContosoUniversity.Services;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain any leftover notifications from static queue (shared across tests)
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotification()
    {
        // Arrange & Act
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("Student", received.EntityType);
        Assert.Equal("42", received.EntityId);
        Assert.Equal("CREATE", received.Operation);
        Assert.Contains("Student 'John Doe'", received.Message);
        Assert.Contains("created", received.Message);
        Assert.Equal("Admin", received.CreatedBy);
        Assert.False(received.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityId()
    {
        // Act
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE, "System");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains("Course (ID: 101)", received.Message);
        Assert.Contains("updated", received.Message);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Department", "5", "Math", EntityOperation.DELETE);

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("System", received.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_VariousOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
    {
        // Act
        _sut.SendNotification("Entity", "1", "TestEntity", operation, "User1");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains(expectedVerb, received.Message);
        Assert.Equal(operation.ToString(), received.Operation);
    }

    [Fact]
    public void SendNotification_Create_MessageStartsWithNew()
    {
        // Act
        _sut.SendNotification("Student", "1", "Alice Smith", EntityOperation.CREATE, "Admin");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.StartsWith("New", received.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Queue already drained in constructor
        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void SendAndReceive_MultipleNotifications_ReturnsInOrder()
    {
        // Arrange
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE, "User");
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE, "User");
        _sut.SendNotification("C", "3", "Third", EntityOperation.DELETE, "User");

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.Equal("A", first!.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _sut.ReceiveNotification();
        Assert.Equal("B", second!.EntityType);
        Assert.Equal("2", second.EntityId);

        var third = _sut.ReceiveNotification();
        Assert.Equal("C", third!.EntityType);
        Assert.Equal("3", third.EntityId);

        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation
        var exception = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesEntityId()
    {
        // Act
        _sut.SendNotification("Student", "7", "", EntityOperation.UPDATE, "Admin");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains("Student (ID: 7)", received.Message);
    }

    [Fact]
    public void SendNotification_WithWhitespaceDisplayName_UsesEntityId()
    {
        // Act
        _sut.SendNotification("Student", "7", "   ", EntityOperation.DELETE, "Admin");

        // Assert
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains("Student (ID: 7)", received.Message);
        Assert.Contains("deleted", received.Message);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.Now.AddSeconds(-1);

        // Act
        _sut.SendNotification("Test", "1", "TestItem", EntityOperation.CREATE, "User");

        // Assert
        var after = DateTime.Now.AddSeconds(1);
        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.InRange(received.CreatedAt, before, after);
    }

    [Fact]
    public void Dispose_CanBeCalledMultipleTimes()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() =>
        {
            service.Dispose();
            service.Dispose();
        });
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_OverloadWithoutDisplayName_DelegatesCorrectly()
    {
        // This tests the two-arg overload that calls the three-arg version
        _sut.SendNotification("Instructor", "10", EntityOperation.CREATE);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Equal("Instructor", received.EntityType);
        Assert.Equal("10", received.EntityId);
        Assert.Contains("Instructor (ID: 10)", received.Message);
        Assert.Contains("created", received.Message);
        Assert.Equal("System", received.CreatedBy);
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_EmptyDatabase_SeedsStudents()
    {
        // Arrange
        using var context = TestHelpers.CreateInMemoryContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(8, context.Students.Count());
        Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
        Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsInstructors()
    {
        // Arrange
        using var context = TestHelpers.CreateInMemoryContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(5, context.Instructors.Count());
        Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
        Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsDepartments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(4, context.Departments.Count());
        Assert.Contains(context.Departments, d => d.Name == "English" && d.Budget == 350000);
        Assert.Contains(context.Departments, d => d.Name == "Economics" && d.Budget == 100000);
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourses()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(7, context.Courses.Count());
        Assert.Contains(context.Courses, c => c.Title == "Chemistry" && c.CourseID == 1050);
        Assert.Contains(context.Courses, c => c.Title == "Calculus" && c.Credits == 4);
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(3, context.OfficeAssignments.Count());
        Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
        Assert.Contains(context.OfficeAssignments, o => o.Location == "Thompson 304");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourseAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsEnrollments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(11, context.Enrollments.Count());
        // Verify some specific enrollments
        var alexanderEnrollments = context.Enrollments.Where(e =>
            context.Students.Any(s => s.ID == e.StudentID && s.LastName == "Alexander"));
        Assert.Equal(3, alexanderEnrollments.Count());
    }

    [Fact]
    public void Initialize_DatabaseAlreadySeeded_DoesNotDuplicateData()
    {
        // Arrange
        using var context = TestHelpers.CreateInMemoryContext();
        DbInitializer.Initialize(context);
        var initialStudentCount = context.Students.Count();
        var initialCourseCount = context.Courses.Count();

        // Act - call Initialize again
        DbInitializer.Initialize(context);

        // Assert - counts should remain the same
        Assert.Equal(initialStudentCount, context.Students.Count());
        Assert.Equal(initialCourseCount, context.Courses.Count());
    }

    [Fact]
