    [Fact]
    public void Create_Post_InvalidExtension_ReturnsViewWithError()
    {
        var course = new Course
        {
            CourseID = 8888,
            Title = "Course With Bad File",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("test.exe");
        mockFile.Setup(f => f.Length).Returns(1024);

        var result = _controller.Create(course, mockFile.Object);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _controller.ModelState["teachingMaterialImage"]!.Errors.First();
        Assert.Contains("valid image file", error.ErrorMessage);
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        var course = new Course
        {
            CourseID = 7777,
            Title = "Large File Course",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("test.jpg");
        mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB > 5MB limit

        var result = _controller.Create(course, mockFile.Object);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _controller.ModelState["teachingMaterialImage"]!.Errors.First();
        Assert.Contains("5MB", error.ErrorMessage);
    }

