    [Fact]
    public void Details_ValidCourse_IncludesDepartment()
    {
        var courseId = _context.Courses.First().CourseID;

        var result = _controller.Details(courseId);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.NotNull(model.Department);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_ValidImageExtension_IsAccepted(string extension)
    {
        // Arrange - create a course and mock file with a valid extension
        var course = new Course
        {
            CourseID = 6000 + extension.GetHashCode() % 1000,
            Title = $"Course {extension}",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns($"test{extension}");
        mockFile.Setup(f => f.Length).Returns(1024);
        var ms = new MemoryStream(new byte[1024]);
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, mockFile.Object);

        // Should either redirect (success) or return view with upload error (filesystem issue)
        // but NOT with extension validation error
        if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
        }
    }
}

