using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new NotificationsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };

        // Drain the static queue so tests start clean
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsView()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        Assert.NotNull(jsonResult.Value);

        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.NotNull(successProp);
        Assert.True((bool)successProp!.GetValue(value)!);

        var countProp = value.GetType().GetProperty("count");
        Assert.NotNull(countProp);
        Assert.Equal(0, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithPendingNotifications_ReturnsNotifications()
    {
        // Arrange - send notifications through the base controller's notification service
        var svc = new NotificationService();
        svc.SendNotification("Student", "1", "John", EntityOperation.CREATE, "Admin");
        svc.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "Admin");
        svc.Dispose();

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);

        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(2, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_LimitsTo10()
    {
        // Arrange - send more than 10 notifications
        var svc = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            svc.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE, "System");
        }
        svc.Dispose();

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.True((int)countProp!.GetValue(value)! <= 10);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(1);

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.NotNull(successProp);
        Assert.True((bool)successProp!.GetValue(value)!);
    }

    [Fact]
    public void MarkAsRead_NonExistentId_StillReturnsSuccess()
    {
        // MarkAsRead is a no-op for in-memory, so any ID should succeed
        var result = _controller.MarkAsRead(99999);

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_ConsumesNotificationsFromQueue()
    {
        // Arrange
        var svc = new NotificationService();
        svc.SendNotification("Test", "1", "TestItem", EntityOperation.CREATE, "User");
        svc.Dispose();

        // Act - first call should get the notification
        _controller.GetNotifications();

        // Act - second call should find empty queue
        var result2 = _controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result2);
        var value = jsonResult.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(0, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_ReturnsNotificationsList()
    {
        // Arrange
        var svc = new NotificationService();
        svc.SendNotification("Student", "42", "Alice", EntityOperation.CREATE, "Admin");
        svc.Dispose();

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var notificationsProp = value.GetType().GetProperty("notifications");
        Assert.NotNull(notificationsProp);
        var notifications = notificationsProp!.GetValue(value) as List<Notification>;
        Assert.NotNull(notifications);
        Assert.Single(notifications!);
        Assert.Equal("Student", notifications[0].EntityType);
        Assert.Equal("42", notifications[0].EntityId);
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Tests for BaseController behavior (notification sending, disposal).
/// Uses a concrete test subclass since BaseController is abstract.
/// </summary>
public class BaseControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly TestableController _controller;

    public BaseControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new TestableController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
        // Drain static queue
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void SendEntityNotification_TwoArgs_DoesNotThrow()
    {
        var ex = Record.Exception(() =>
            _controller.TestSendEntityNotification("Student", "1", EntityOperation.CREATE));

        Assert.Null(ex);
    }

    [Fact]
    public void SendEntityNotification_ThreeArgs_EnqueuesNotification()
    {
        // Act
        _controller.TestSendEntityNotification("Course", "101", "Calculus", EntityOperation.UPDATE);

        // Assert - check the static queue
        var svc = new NotificationService();
        var notification = svc.ReceiveNotification();
        svc.Dispose();

        Assert.NotNull(notification);
        Assert.Equal("Course", notification!.EntityType);
        Assert.Equal("101", notification.EntityId);
        Assert.Contains("updated", notification.Message);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendEntityNotification_WithDisplayName_IncludesNameInMessage()
    {
        _controller.TestSendEntityNotification("Student", "5", "John Doe", EntityOperation.CREATE);

        var svc = new NotificationService();
        var notification = svc.ReceiveNotification();
        svc.Dispose();

        Assert.NotNull(notification);
        Assert.Contains("John Doe", notification!.Message);
    }

    [Fact]
    public void SendEntityNotification_WithoutDisplayName_FallsBackToId()
    {
        _controller.TestSendEntityNotification("Student", "5", EntityOperation.DELETE);

        var svc = new NotificationService();
        var notification = svc.ReceiveNotification();
        svc.Dispose();

        Assert.NotNull(notification);
        Assert.Contains("ID: 5", notification!.Message);
    }

    [Fact]
    public void Dispose_CanBeCalledSafely()
    {
        var ctx = TestHelpers.CreateInMemoryContext();
        var ctrl = new TestableController(ctx);

        var ex = Record.Exception(() => ctrl.Dispose());

        Assert.Null(ex);
    }

    [Fact]
    public void Constructor_SetsDbContext()
    {
        Assert.NotNull(_controller.GetDb());
        Assert.Same(_context, _controller.GetDb());
    }

    /// <summary>
    /// Concrete subclass exposing protected members for testing.
    /// </summary>
    private class TestableController : BaseController
    {
        public TestableController(SchoolContext context) : base(context) { }

        public void TestSendEntityNotification(string entityType, string entityId, EntityOperation operation)
        {
            SendEntityNotification(entityType, entityId, operation);
        }

        public void TestSendEntityNotification(string entityType, string entityId, string displayName, EntityOperation operation)
        {
            SendEntityNotification(entityType, entityId, displayName, operation);
        }

        public SchoolContext GetDb() => db;
    }
}

