+        var svc = new NotificationService();
+        var notification = svc.ReceiveNotification();
+        svc.Dispose();
+
+        Assert.NotNull(notification);
+        Assert.Contains("ID: 5", notification!.Message);
+    }
+
+    [Fact]
+    public void Dispose_CanBeCalledSafely()
+    {
+        var ctx = TestHelpers.CreateInMemoryContext();
+        var ctrl = new TestableController(ctx);
+
+        var ex = Record.Exception(() => ctrl.Dispose());
+
+        Assert.Null(ex);
+    }
+
+    [Fact]
+    public void Constructor_SetsDbContext()
+    {
+        Assert.NotNull(_controller.GetDb());
+        Assert.Same(_context, _controller.GetDb());
+    }
+
+    /// <summary>
