+            EntityId = "1",
+            Operation = "CREATE",
+            Message = "Test",
+            CreatedAt = DateTime.Now,
+            CreatedBy = "Test",
+            IsRead = false
+        };
+
+        context.Notifications.Add(notification);
+        context.SaveChanges();
+
+        Assert.Single(context.Notifications);
+        Assert.True(context.Notifications.First().Id > 0);
+    }
