    [Fact]
    public void SendNotification_ExceedsMaxQueueLength_EnforcesLimit()
    {
        // Send 505 notifications (more than _maxQueueLength of 500)
        for (int i = 0; i < 505; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        // Count remaining via dequeue
        int count = 0;
        while (_sut.ReceiveNotification() != null) count++;

        Assert.True(count <= 500, $"Queue had {count} items, should be capped at 500");
    }

    [Fact]
    public void SendNotification_AllNewNotifications_AreUnread()
    {
        // Send multiple notifications
        for (int i = 0; i < 5; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
        }

        Notification? notification;
        int checkedCount = 0;
        while ((notification = _sut.ReceiveNotification()) != null)
        {
            Assert.False(notification.IsRead, $"Notification {notification.EntityId} should be unread");
            checkedCount++;
        }
        Assert.Equal(5, checkedCount);
    }

    [Fact]
    public void SendNotification_WithNullDisplayName_UsesEntityId()
    {
        _sut.SendNotification("Student", "7", null, EntityOperation.UPDATE, "Admin");

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.Contains("Student (ID: 7)", received.Message);
        Assert.Equal("Admin", received.CreatedBy);
        Assert.NotNull(received.CreatedBy);
        Assert.NotEmpty(received.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithNullUserName_CreatedByIsNeverNullOrEmpty()
    {
        _sut.SendNotification("Entity", "1", null, EntityOperation.CREATE, null);

        var received = _sut.ReceiveNotification();
        Assert.NotNull(received);
        Assert.NotNull(received.CreatedBy);
        Assert.NotEmpty(received.CreatedBy);
        Assert.Equal("System", received.CreatedBy);
    }
}

