    [Fact]
    public void Constructor_SetsPropertiesCorrectly()
    {
        var items = new List<int> { 1, 2, 3 };

        var list = new PaginatedList<int>(items, 30, 2, 10);

        Assert.Equal(2, list.PageIndex);
        Assert.Equal(3, list.TotalPages);
        Assert.Equal(3, list.Count);
        Assert.Contains(1, list);
        Assert.Contains(2, list);
        Assert.Contains(3, list);
    }

    [Fact]
    public void TotalPages_WithPageSize1_CalculatesCorrectly()
    {
        var items = new List<int> { 1 };
        var list = new PaginatedList<int>(items, 5, 1, 1);

        // 5 total items, page size 1 = 5 pages
        Assert.Equal(5, list.TotalPages);
    }

    [Fact]
    public void TotalPages_51ItemsPageSize10_Equals6Pages()
    {
        var source = CreateTestSource(51);
        var result = PaginatedList<string>.Create(source, 1, 10);

        // Should round UP to 6 pages (not floor to 5)
        Assert.Equal(6, result.TotalPages);
    }

    [Fact]
    public void Create_Page3_WithPageSize25_StartsAtCorrectPosition()
    {
        var source = CreateTestSource(100);
        var result = PaginatedList<string>.Create(source, 3, 25);

        // Page 3, size 25: skip (3-1)*25 = 50
        Assert.Equal("Item51", result[0]);
        Assert.Equal("Item75", result[24]);
        Assert.Equal(25, result.Count);
    }

    [Fact]
    public void HasPreviousPage_PageIndex1_StrictlyFalse_MutationGuard()
    {
        // Guards against changing > to >= in HasPreviousPage
        var source = CreateTestSource(50);
        var result = PaginatedList<string>.Create(source, 1, 10);

        Assert.Equal(1, result.PageIndex);
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_StrictlyFalse_MutationGuard()
    {
        // Guards against changing < to <= in HasNextPage
        var source = CreateTestSource(30);
        var result = PaginatedList<string>.Create(source, 3, 10);

        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.False(result.HasNextPage);
    }
}

