    public void Index_SetsViewBagProperties()
    {
        _controller.Index("name_desc", "filter", null, 2);

        Assert.Equal("name_desc", _controller.ViewBag.CurrentSort);
        Assert.Equal("filter", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Index_WithManyStudents_ReturnsPageSize10()
    {
        // Seed additional students to exceed page size
        for (int i = 0; i < 15; i++)
        {
            _context.Students.Add(new Student
            {
                FirstMidName = $"First{i}",
                LastName = $"Last{i}",
                EnrollmentDate = DateTime.Today
            });
        }
        _context.SaveChanges();

        var result = _controller.Index(null, null, null, 1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(10, model.Count); // Exactly page size 10
        Assert.True(model.TotalPages >= 2);
        Assert.True(model.HasNextPage);
    }

    [Fact]
    public void Index_DefaultSort_WithOutOfOrderData_SortsAscending()
    {
        // Use a fresh context with deliberately unordered data
        using var ctx = TestHelpers.CreateInMemoryContext();
        ctx.Students.AddRange(
            new Student { FirstMidName = "A", LastName = "Zebra", EnrollmentDate = DateTime.Today },
            new Student { FirstMidName = "B", LastName = "Apple", EnrollmentDate = DateTime.Today },
            new Student { FirstMidName = "C", LastName = "Mango", EnrollmentDate = DateTime.Today }
        );
        ctx.SaveChanges();

        using var ctrl = new StudentsController(ctx);
        ctrl.ControllerContext = new ControllerContext { HttpContext = new DefaultHttpContext() };

        var result = ctrl.Index(null, null, null, null);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(((ViewResult)result).Model);

        Assert.Equal("Apple", model[0].LastName);
        Assert.Equal("Mango", model[1].LastName);
        Assert.Equal("Zebra", model[2].LastName);
    }

    [Fact]
    public void Create_Post_ValidStudent_SendsNotification()
    {
        // Drain queue
        var drainSvc = new ContosoUniversity.Services.NotificationService();
        while (drainSvc.ReceiveNotification() != null) { }

        var student = new Student
        {
            LastName = "Notified",
            FirstMidName = "Test",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        _controller.Create(student);

        // Verify notification was sent
        var notification = drainSvc.ReceiveNotification();
        drainSvc.Dispose();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification!.EntityType);
        Assert.Contains("created", notification.Message);
        Assert.Contains("Notified", notification.Message);
    }

    [Fact]
    public void DeleteConfirmed_SendsDeleteNotification()
    {
        // Drain queue
        var drainSvc = new ContosoUniversity.Services.NotificationService();
        while (drainSvc.ReceiveNotification() != null) { }

        var student = _context.Students.First();
        _controller.DeleteConfirmed(student.ID);

        var notification = drainSvc.ReceiveNotification();
        drainSvc.Dispose();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification!.EntityType);
        Assert.Contains("deleted", notification.Message);
    }
}

